mapper.sql:
P.SUB_CATEGORY_NO IN(
		SELECT CATEGORY_NO FROM CATEGORY
		START WITH CATEGORY_NO = #{categoryNo}
		CONNECT BY PRIOR CATEGORY_NO = PARENT_CATEGORY_NO
)

	WHERE 

 AND (NVL(P.PRODUCT_PRICE, 0) + NVL(OPT.PRICE, 0)) BETWEEN #{minPrice} AND #{maxPrice}
 AND NVL(RV.AVG_RATING, 0) >=#{rating}

 AND OPT.OPTION_ID IS NOT NULL

mapper.select:
SELECT CATEGORY_NO, CATEGORY_NAME, PARENT_CATEGORY_NO, CATEGORY_LEVEL
FROM CATEGORY
WHERE CATEGORY_NO = #{categoryNo}
